// This file is generated by AI.

// 最近项目卡片 (开始界面): 封面 + 名称 + 上次打开时间, 右下角一个常驻的操作菜单。

import { ImageRegular, MoreVerticalRegular } from '@fluentui/react-icons';

import { useImageUrl } from '../lib/localImage';
import { joinPath } from '../lib/paths';
import { formatRelativeTime } from '../lib/recentProjects';

export interface RecentProjectView {
  path: string;
  name: string;
  /** `Title_img` (仅文件名) */
  titleImg?: string;
  lastOpened: number;
  /** 目录是否还在 (被移动/删除的项目仍然留在列表里, 但要看得出来) */
  available: boolean;
}

interface Props {
  project: RecentProjectView;
  onOpen: () => void;
  /** 操作菜单位置 (由"更多"按钮的实际位置算出) */
  onMenu: (position: { x: number; y: number }) => void;
  onContextMenu: (event: React.MouseEvent) => void;
}

export function RecentProjectCard({ project, onOpen, onMenu, onContextMenu }: Props) {
  /*
   * 封面图直接读 `game/background/<Title_img>` 的字节。
   *
   * 不用预览服务器: 开始界面没有打开任何项目, 为了十几张缩略图去注册十几个站点
   * 代价太大 (而且这些站点会一直留着)。目录不在时连读都不读。
   */
  const coverPath =
    project.available && project.titleImg ? joinPath(project.path, 'game', 'background', project.titleImg) : null;
  const cover = useImageUrl(coverPath);

  return (
    <article
      className={`project-card${project.available ? '' : ' unavailable'}`}
      title={project.path}
      onClick={onOpen}
      onContextMenu={onContextMenu}
    >
      <div className="project-cover">
        {cover ? (
          <img src={cover} alt="" draggable={false} />
        ) : (
          <span className="project-cover-placeholder" aria-hidden="true">
            <ImageRegular />
          </span>
        )}
        {project.available ? null : <span className="project-badge">位置不可用</span>}
      </div>

      <div className="project-card-body">
        <h4 className="project-card-name">{project.name}</h4>
        <div className="project-card-row">
          <span className="project-card-time">{formatRelativeTime(project.lastOpened)}</span>
          {/*
            常驻的"更多"按钮: 三个悬浮才出现的小图标既难点中也看不见 (触屏上基本等于没有),
            而所有操作本来就在右键菜单里, 于是这里只留一个入口, 菜单内容与右键完全一致。
            竖排三点与文件树的"更多操作"保持一致 —— 同一套界面里两种方向的省略号会显得很随意。
          */}
          <button
            type="button"
            className="project-card-menu"
            title="更多操作"
            aria-label="更多操作"
            onClick={(event) => {
              event.stopPropagation();
              const rect = event.currentTarget.getBoundingClientRect();
              onMenu({ x: rect.right, y: rect.bottom });
            }}
          >
            <MoreVerticalRegular />
          </button>
        </div>
      </div>
    </article>
  );
}
